mapper.select:
select rindex.PRI_ID,rindex.INDEX_NAME,rindex.INDEX_VALUE
from REP_INDEX_SUB rindex
where
    AUDIT_STATUS='E'

    	and rindex.PRI_ID=#{indexId,jdbcType}


    	and INDEX_DATE<#{reportDate,jdbcType=DATE}

select dpa.PROD_ID ,dpa.FIX_PRE_RATIO ,dpa.FIX_AFTER_RATIO ,dpa.EQUITY_PRE_RATIO ,dpa.EQUITY_AFTER_RATIO ,dpa.FD_PRE_RATIO ,dpa.FD_AFTER_RATIO ,dpa.MIX_PRE_RATIO ,dpa.MIX_AFTER_RATIO from DIS_PROD_ASSET dpa where dpa.DATA_STATUS='E'
and PROD_ID=#{prodId,jdbcType=VARCHAR}
and #{reportDate,jdbcType=DATE} between dpa.EFF_DATE and dpa.EFF_END_DATE

select rac.PROD_ID ,rac.PUB_DATE ,rac.ASSETS_CODE ,rac.ASSETS_NAME ,rac.FAIR_VALUE ,rac.PD_PROP from REP_ASSETS_COMB rac where rac.DATA_STATUS='E'
and rac.PROD_ID=#{prodId,jdbcType=VARCHAR}
and rac.PUB_DATE = #{reportDate,jdbcType=DATE}

select deal.PROD_ID ,deal.PUB_DATE ,deal.BANK_TRANS_AMT ,deal.ORG_TRANS_AMT ,deal.INVEST_TRANS_AMT from REP_REL_DEAL deal where deal.DATA_STATUS='E'
and deal.PROD_ID=#{prodId,jdbcType=VARCHAR}
and deal.PUB_DATE = #{reportDate,jdbcType=DATE}
